"""Computes the precision score of one image.

    Parameters
    ----------
    label : string
            The true label of the image
    predictions : list
            A list of predicted elements (order does matter, k predictions allowed per image)

    k : int
            MAP@k

    Returns
    -------
    score : double
    """
def map_per_image(label: Any, predictions: Any, k: int = 5) -> object {
    try {
        return (1 / (predictions[:k].index(label) + 1));
    } except ValueError {
        return 0.0;
    }
}

"""Destructures a dictionary (vaguely like ES6 for JS)
       Results are SORTED by key alphabetically! You must sort your receiving vars
    """
def pluck(input_dictionary: Any) -> object {
    items = sorted(input_dictionary.items());
    return [item[1] for item in items];
}

"""
    Unboxes a JSON payload object expected by the server into
    a list of alias names.
    """
def payload_to_list(alias_payload: Any) -> object {
    return [record["value"] for record in alias_payload["aliases"]];
}

"""
  mod      ::= 0(reset)|1(bold)|2(faint)|3(italic)|4(underline)
  int      ::= 9(intense fg) | 3(normal bg)
  clr      ::= 0(blk)|1(red)|2(grn)|3(ylw)|4(blu)|5(mag)|6(cyn)|7(wht)
  """
def _c(s: Any, modifier: Any = 0, intensity: Any = 3, color: Any = 0) -> object {
    escape = "\x1b[";
    reset_modifier = 0;
    ns = f"{escape}{modifier};{intensity}{color}m{s}{escape}{reset_modifier}m";
    return ns;
}

"""Greatest Common Divisor by Euclid"""
def gcd(a: Any, b: Any) -> object {
    a = abs(a);
    b = abs(b);
    if ((a == 0) and (b == 0)) {
        return 1;
    }
    if (a == 0) {
        return b;
    }
    if (b == 0) {
        return a;
    }
    if (a < b) {
        (a, b) = (b, a);
    }
    r = 1;
    while r {
        r = a % b;
        if r {
            a = b;
            b = r;
        }
    }
    return b;
}

